; 22 x u8 monotone map 0..12.  MidiSeq_UpdateToneParam (0xFD6C39) and
; MidiSeq_UpdateToneParam_Lower (0xFD6C69): `lda xbc,(<this>); ld c, (xbc+hl)`,
; the byte is stored to RAM 0xBD00.
MidiRx_ToneParam_ByteMap:
	.byte 0, 1, 1, 2, 3, 3, 4, 5, 5, 5, 6, 7, 7, 7, 8, 9, 9, 10, 11, 11, 11, 12
; 36 x u8 (0x20-0x23, 0x0F, one 0xFF).  MidiSeq_PartLookup_Data_Helper3 (0xFD6DCE):
; `lda xbc,(<this>); ld (0x7F42),(xbc+hl)` -- copies the indexed byte to RAM.
MidiRx_PartLookup_ByteMap:
	.byte 0x23, 0x21, 0x21, 0x21, 0x21, 0x21, 0x21, 0x21, 0x22, 0x22, 0x22, 0x21, 0x21, 0x21, 0x21, 0x21, 0x21, 0x21
	.byte 0x21, 0x21, 0x21, 0x21, 0x0f, 0x21, 0x20, 0x21, 0x21, 0x21, 0x21, 0x21, 0x21, 0x21, 0x20, 0x20, 0x21, 0xff
; 16-byte template: ArpQueue_InitBuffer (0xFD7C01) copies it into the queue buffer
; (`ld xiy,<this>; ld xix,xde; ldw bc,8; ldirw`).
ArpQueue_InitTemplate:
	.byte 0x00, 0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff
; 40 bytes of MIDI control records.  0xEE49E8 is the sentinel
; MidiPkt_MatchParamInTable (0xFD9A87) stops at (`lda xix,(<this>)`, `cp xix,xhl;
; ret z`) and MidiPkt_EnqueueControl_3354 (0xFD9AA7) compares record pointers against;
; readers take +2/+3/+7/+8/+11 of such records.  Record boundaries inside
; these 40 bytes (and in the records after them) are not established yet.
; MIDI control records, 20 bytes each (41: 0xEE49E8, 0xEE49FC, then 39 from
; 0xEE4A5E).  Stride from the pointer lists below, which only ever point at
; these 41 addresses.  Fields a reader was seen to use:
;   +6/+7/+8  MidiPkt_MatchParamInTable (0xFD9A87): `cp c,(xhl+7)` against the
;             message's data byte, `and c,(xhl+8)` mask; +6 holds status-like
;             values (0x90/0x91/0x98/0xB0 ...) or object codes (0x43, 0x48, 0x60-0x66)
;   +9/+10    lower / upper bound (SeqAlt_* `cp (xiz+9),l` / `cp l,(xiz+10)`)
;   +14       sub-table index, 0xFF = none (SeqAlt_*: `cp a,255`, `cp a,1`)
;   +16/+17/+18  handler indices into MidiCtl_Handlers (0-5),
;             MidiCtl_FormatHandlers (0-11), MidiCtl_AssSwbHandlers (0-5) --
;             `ld c,(xbc+16/17/18); sla bc,2; call (table+bc)`
;   +19       0xFF in every record.
; The value ranges of +16/+17/+18 over the 41 records equal the three tables'
; sizes.  MidiCtl_NullRecord (0xEE49E8) is the list terminator
; MidiPkt_MatchParamInTable stops on (`lda xix,(<this>)`, `cp xix,xhl; ret z`).
; The bytes at 0xEE4AF0 (+6..+9 of MidiCtl_Rec_09, 0x00FF0017) were typed as a
; `.long` "SendPartDataBlock_Data3" pointer: v7 has the same bytes although its
; SendPartDataBlock_Data3 is at 0xFEFC57, so they are not a pointer.
MidiCtl_NullRecord:
	.byte 0x0a, 0x00, 0x00, 0x00, 0x00, 0x01, 0xb0, 0x01, 0x7f, 0x00, 0x7f, 0x00, 0x00, 0x00, 0xff, 0x00, 0x00, 0x00, 0x01, 0xff
; MIDI control record 1 (20 bytes, layout at MidiCtl_NullRecord);
; reached through the MidiCtl_SelectTable* pointers.
MidiCtl_Rec_01:
	.byte 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x91, 0x00, 0xff, 0xc0, 0x3f, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x0b, 0x01, 0xff
; 78 x s8 ramp -64 .. +63: the only sub-table of MidiCtl_SubTableDesc
; (length 0x4E = 78, pointer = this), used by SeqAlt_ApplyDescriptor_TypeA
; (0xFD91E1) when a record's +14 is 0.  Legacy name ToneKit_FrequencyTable kept
; as an alias: shared/positional_labels.s derives 16 _0xNN names from it.
MidiCtl_SignedRamp78:
	.set ToneKit_FrequencyTable, MidiCtl_SignedRamp78
	.byte -64, -63, -61, -60, -58, -56, -54, -53, -51, -49, -48, -46, -44, -42, -41, -39
	.byte -37, -36, -34, -32, -30, -29, -27, -25, -24, -22, -20, -19, -17, -15, -13, -12
	.byte -10, -8, -7, -5, -3, -2, 0, 2, 3, 5, 7, 8, 10, 12, 13, 15
	.byte 17, 18, 20, 22, 23, 25, 27, 28, 30, 32, 33, 35, 37, 38, 40, 42
	.byte 43, 45, 47, 48, 50, 51, 53, 55, 56, 58, 60, 61, 62, 63
; MIDI control record 2 (20 bytes, layout at MidiCtl_NullRecord);
