; -----------------------------------------------------------------------------
; Seven small arrays read by audio/dsp_config_sysex.s through positional
; names (DspCfg_Data001_ByteTable .. _0x348).
; -----------------------------------------------------------------------------
; byte[n], read by DSPCfg_Data_001 (0xFDBC77: `add xbc,xwa / ld l,(xbc)`).  No
; call of DSPCfg_Data_001 was found (call/calr/jp/jr target scan of the v10
; ELF disassembly), so the index range and purpose are not established.
DspCfg_Data001_ByteTable:	.byte 0, 0, 0, 0
; byte[n], read by DSPCfg_Data_002 (0xFDBC93), same shape; no caller found
; by the same scan; purpose not established.
DspCfg_Data002_ByteTable:	.byte 1, 1, 1, 1
; DSP block index 0..5 -> object code.  DSPCfg_LookupMidiMap (0xFDB7F5) passes
; byte[block] to PanelTlv_PayloadOfTag; DSPCfg_ResolveParamToSlot_Range49..4E
; call it with the block of the 0x49xx..0x4Exx parameter id; and
; DSPCfg_WriteParamFull / DSPCfg_WriteAllSlots_Direct post byte[block] as the
; SwbtWr event code through AssswbWr.  The SwbtWr bank-2 lists of exactly
; these five codes (0x61, 0x63, 0x64, 0x65, 0x66) contain EffEdit_DSPConfigBlock;
; code 0x62's list does not.  The values happen to be ASCII 'a','c','e','f','d';
; they are codes, not text.  0xFF = no object.
DspBlock_ObjectCode_Table:	.byte 0x61, 0x63, 0x65, 0x66, 0x64, 0xff
; parameter id 0x4900+i (i = 0..7) -> signed byte, stored through the caller's
; pointer by DSPCfg_DecodeParamIdRange (0xFDBD33: `sub xwa,0x4900`, `cp xwa,7`,
; `add xwa,<this>`, `ld c,(xwa) / exts bc`).
DspParamId4900_ByteMap:	.byte 0, 2, 6, 3, 8, 5, 9, 7
; u16[i], read by DSPCfg_ResolveWithFallback (0xFDBF3F) as `add xwa,xwa` index
; then `sll bc,8`; purpose of the resulting value not established.
DspCfg_ResolveFallback_WordTable:	.short 0, 2, 4, 5, 3
; switch table: u16 offset per op letter 'a'..'f' (`sub wa,97`, `cp wa,5`),
; jumped to as 0xFDCCD3 + offset by the code after DSPCfg_Data_ParamDispatch
; (`jp t, (xix+wa)`).  The targets have no labels yet, so the offsets stay
; numeric: 0xFDCCD3, 0xFDCCDC, 0xFDCCE3, 0xFDCCEC, 0xFDCCF5, 0xFDCCFE (v10).
DspCfg_OpLetter_JumpOffsets:
	.short	DSPCfg_Data_ParamDispatch_Code - DSPCfg_Data_ParamDispatch_Code
	.short	EffEdit_DSPConfigBlock_Helper_Case98 - DSPCfg_Data_ParamDispatch_Code
	.short	EffEdit_DSPConfigBlock_Helper_Case99 - DSPCfg_Data_ParamDispatch_Code
	.short	EffEdit_DSPConfigBlock_Helper_Case100 - DSPCfg_Data_ParamDispatch_Code
	.short	EffEdit_DSPConfigBlock_Helper_Case101 - DSPCfg_Data_ParamDispatch_Code
	.short	EffEdit_DSPConfigBlock_Helper_Case102 - DSPCfg_Data_ParamDispatch_Code
; switch table: u16 offset from AssSwb_SwapEntriesAndDispatch, 21 entries,
; used by DspConfig_EventDispatch (0xFDCACC: index = type-1 for 0..8, or
; type-1-0x12 for 9..20; `add bc,bc`, `ld r, (xrr+rr)`, `jp t, (xrr+rr)`).  Offset 0 is the
; default (AssSwb_SwapEntriesAndDispatch itself); the other targets have no
; labels yet.
DspConfig_EventDispatch_JumpOffsets:
	.short	DSPCfg_ApplyParamStructFull_Case18 - AssSwb_SwapEntriesAndDispatch
	.short	DSPCfg_ApplyParamStructFull_Case19 - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	DSPCfg_ApplyParamStructFull_Case21 - AssSwb_SwapEntriesAndDispatch
	.short	DSPCfg_ApplyParamStructFull_Case22 - AssSwb_SwapEntriesAndDispatch
	.short	DSPCfg_ApplyParamStructFull_Case23 - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	DSPCfg_ApplyParamStructFull_Case26 - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	AssSwb_SwapEntriesAndDispatch - AssSwb_SwapEntriesAndDispatch
	.short	DSPCfg_ApplyParamStructFull_Case31 - AssSwb_SwapEntriesAndDispatch
