	.long	AccPatch_InitFuncTable
	.long	SoundRam_HandlerTable
	.long	FDemoText_InitFuncTable
	.long CharMap_Preamble_Table
	.long 0x00000000
; 6 bytes 0,1,2,3,4,0xFF after the list's 0 terminator.  No reader: neither an
; instruction operand nor a 32-bit data pointer in the v10 ROM names 0xEE8CCE.
; Purpose not established.
NoRef_Bytes_EE8CCE:
	.byte 0x00, 0x01, 0x02, 0x03, 0x04, 0xff
; 16 x u16 single-bit masks 1<<i (i = 0..15).  Read with `lda xix,(<this>);
; ld_rrw wa,xix,wa` by AudioInit_NoTypeE_CheckD + 26 (0xFDECF2) and five more
; AudioInit_* routines and and-ed with a channel mask (AudioInit_ChannelLoop_Body:
; `andda16 xwa,(0xF290)`).
Bit16Mask_Table:
	.short 0x0001, 0x0002, 0x0004, 0x0008, 0x0010, 0x0020, 0x0040, 0x0080
	.short 0x0100, 0x0200, 0x0400, 0x0800, 0x1000, 0x2000, 0x4000, 0x8000
; 32 x u32 routine pointers indexed by RAM byte 0x8D34.  AudioModeChange_Handler
; (0xFDDE1A), AudioSubsystem_Callback (0xFDD6C9), AudioVoice_Callback (0xFDDF67)
; and AudioVoiceReset_Handler (0xFDDFC1): `ldb_d8 a,(0x8d34); sla wa,2;
; lda xbc,(<this>); ld_rrl xhl,xbc,wa`, skip (`ret z`) when the entry equals
; 0xFDE509 in v7 (v10/v9: 0xFDECEF, AudioInit_MixFallbackDefault+5) -- no entry of this
