; 6 x s8 (-12, 12, 5, 12, -10, -5), read one at a time with `ldb_da e,(addr)`
; and subtracted from RAM 0xCEAA: SoundFX_Handler_9 (0xFE8B6E) uses +0/+1,
; SoundFX_Handler_10 (0xFE8B91) +2/+3, SoundFX_Handler_11 (0xFE8BB4) +4/+5.
